// Category constants define the standard feature flag categories used in Prometheus.
const (
	API                       = "api"
	OTLPReceiver              = "otlp_receiver"
	Prometheus                = "prometheus"
	PromQL                    = "promql"
	PromQLFunctions           = "promql_functions"
	PromQLOperators           = "promql_operators"
