package main

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/prometheus/prometheus/config"
	api_v1 "github.com/prometheus/prometheus/web/api/v1"
)

const transactionalReloadStateFilename = "reload-status.json"

// transactionalReloader coordinates a reload attempt and retains the last
// configuration that was completely applied.
type transactionalReloader struct {
	logger    *slog.Logger
	stateFile string

	mu        sync.RWMutex
	status    api_v1.ReloadStatus
	knownGood *config.Config
}

func newTransactionalReloader(storageDir string, logger *slog.Logger) *transactionalReloader {
	t := &transactionalReloader{
		logger:    logger,
		stateFile: filepath.Join(storageDir, transactionalReloadStateFilename),
		status:    emptyReloadStatus(),
	}

	b, err := os.ReadFile(t.stateFile)
	if err == nil {
		var status api_v1.ReloadStatus
		if err := json.Unmarshal(b, &status); err != nil {
			logger.Warn("Ignoring corrupted transactional reload status", "filename", t.stateFile, "err", err)
		} else if !validReloadStatus(status) {
			logger.Warn("Ignoring invalid transactional reload status", "filename", t.stateFile)
		} else {
			t.status = normalizedReloadStatus(status)
		}
	} else if !os.IsNotExist(err) {
		logger.Warn("Unable to read transactional reload status", "filename", t.stateFile, "err", err)
	}
	return t
}

func validReloadStatus(status api_v1.ReloadStatus) bool {
	if status.LastReloadID != "" {
		if _, err := time.Parse(time.RFC3339, status.LastReloadID); err != nil {
			return false
		}
	}
	switch status.ErrorCategory {
	case "", "none", "load_error", "apply_error", "rollback_error":
		return true
	default:
		return false
	}
}

func emptyReloadStatus() api_v1.ReloadStatus {
	return api_v1.ReloadStatus{
		ErrorCategory:     "none",
		AppliedReloaders:  []string{},
		ReloaderTimingsMS: map[string]float64{},
	}
}

func normalizedReloadStatus(status api_v1.ReloadStatus) api_v1.ReloadStatus {
	if status.AppliedReloaders == nil {
		status.AppliedReloaders = []string{}
	}
	if status.ReloaderTimingsMS == nil {
		status.ReloaderTimingsMS = map[string]float64{}
	}
	if status.ErrorCategory == "" {
		status.ErrorCategory = "none"
	}
	return status
}

func (t *transactionalReloader) Status() api_v1.ReloadStatus {
	t.mu.RLock()
	defer t.mu.RUnlock()
	status := t.status
	status.AppliedReloaders = append([]string(nil), status.AppliedReloaders...)
	status.ReloaderTimingsMS = make(map[string]float64, len(status.ReloaderTimingsMS))
	for name, timing := range status.ReloaderTimingsMS {
		status.ReloaderTimingsMS[name] = timing
	}
	return status
}

func (t *transactionalReloader) setKnownGood(conf *config.Config) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.knownGood = conf
}

func (t *transactionalReloader) recordLoadError(err error) {
	t.record(api_v1.ReloadStatus{
		LastReloadID:         time.Now().UTC().Format(time.RFC3339Nano),
		LastReloadSuccessful: false,
		ErrorCategory:        "load_error",
		ErrorMessage:         err.Error(),
		AppliedReloaders:     []string{},
		ReloaderTimingsMS:    map[string]float64{},
	})
}

func (t *transactionalReloader) apply(conf *config.Config, reloaders []reloader, recordOutcome bool) error {
	status := api_v1.ReloadStatus{
		LastReloadID:         time.Now().UTC().Format(time.RFC3339Nano),
		AppliedReloaders:     []string{},
		ReloaderTimingsMS:    map[string]float64{},
		ErrorCategory:        "none",
		LastReloadSuccessful: true,
	}

	for _, rl := range reloaders {
		start := time.Now()
		err := rl.reloader(conf)
		status.ReloaderTimingsMS[rl.name] = float64(time.Since(start)) / float64(time.Millisecond)
		if err == nil {
			status.AppliedReloaders = append(status.AppliedReloaders, rl.name)
			continue
		}

		status.LastReloadSuccessful = false
		status.ErrorCategory = "apply_error"
		status.ErrorMessage = err.Error()
		status.FailedReloader = rl.name

		t.mu.RLock()
		knownGood := t.knownGood
		t.mu.RUnlock()
		if len(status.AppliedReloaders) > 0 && knownGood != nil {
			status.RollbackAttempted = true
			status.RollbackSuccessful = true
			for _, rollback := range reloaders {
				if rollbackErr := rollback.reloader(knownGood); rollbackErr != nil {
					status.RollbackSuccessful = false
					status.ErrorCategory = "rollback_error"
					status.ErrorMessage = fmt.Sprintf("applying %s failed: %v; rollback %s failed: %v", rl.name, err, rollback.name, rollbackErr)
					break
				}
			}
		}
		if recordOutcome {
			t.record(status)
		}
		return fmt.Errorf("failed to apply configuration with reloader %q: %w", rl.name, err)
	}

	t.setKnownGood(conf)
	if recordOutcome {
		t.record(status)
	}
	return nil
}

